def count_right_triangles(N, points):
    from collections import defaultdict

    x_map = defaultdict(list)
    y_map = defaultdict(list)

    for x, y in points:
        x_map[x].append(y)
        y_map[y].append(x)

    triangle_count = 0

    for x, y in points:
        # Count points with the same x-coordinate
        if len(x_map[x]) > 1:
            # For each pair of points with the same x-coordinate, check if there's a point with the same y-coordinate
            for y2 in x_map[x]:
                if y2 != y:
                    triangle_count += len(y_map[y]) - 1  # Subtract 1 to exclude the point itself

        # Count points with the same y-coordinate
        if len(y_map[y]) > 1:
            # For each pair of points with the same y-coordinate, check if there's a point with the same x-coordinate
            for x2 in y_map[y]:
                if x2 != x:
                    triangle_count += len(x_map[x]) - 1  # Subtract 1 to exclude the point itself

    # Each triangle is counted twice (once for each leg), so divide by 2
    return triangle_count // 2

